{
  "message": "Implemented validated debit/credit batches and precision-preserving JSON output.",
  "rationale": "The discriminated union enforces event-specific fields, strict account IDs, Decimal constraints, and per-call caps with indexed validation errors. JSON decoding preserves numeric decimal precision, and serialization includes aliases and computed signed amounts while omitting None.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "import json
from decimal import Decimal
from typing import Annotated, Literal, Union

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    TypeAdapter,
    ValidationError,
    ValidationInfo,
    computed_field,
    field_validator,
)


class Event(BaseModel):
    model_config = ConfigDict(extra='forbid', populate_by_name=True)

    kind: str
    account_id: int = Field(alias='accountId', strict=True, gt=0)
    amount: Decimal = Field(gt=0, decimal_places=2, allow_inf_nan=False)
    currency: Literal['USD', 'EUR']

    @field_validator('amount')
    @classmethod
    def validate_cap(cls, amount: Decimal, info: ValidationInfo) -> Decimal:
        if info.context is not None and amount > info.context['cap']:
            raise ValueError('amount exceeds cap')
        return amount

    @computed_field
    @property
    def signed(self) -> Decimal:
        return self.amount.copy_negate() if self.kind == 'debit' else self.amount


class Debit(Event):
    kind: Literal['debit']
    reason: str = Field(min_length=3)


class Credit(Event):
    kind: Literal['credit']
    reference: str | None = None


_BATCH_ADAPTER = TypeAdapter(
    Annotated[
        list[Annotated[Union[Debit, Credit], Field(discriminator='kind')]],
        Field(strict=True),
    ]
)
_CAP_ADAPTER = TypeAdapter(Annotated[Decimal, Field(allow_inf_nan=False)])


def parse_batch(payload, cap='100.00'):
    limit = _CAP_ADAPTER.validate_python(cap)
    if isinstance(payload, (str, bytes)):
        original = payload
        try:
            if isinstance(payload, bytes):
                payload = payload.decode('utf-8')
            payload = json.loads(payload, parse_float=Decimal)
        except ValueError as exc:
            raise ValidationError.from_exception_data(
                'Batch',
                [
                    {
                        'type': 'json_invalid',
                        'loc': (),
                        'input': original,
                        'ctx': {'error': str(exc)},
                    }
                ],
            ) from exc
    return _BATCH_ADAPTER.validate_python(payload, context={'cap': limit})


def dump_batch(events):
    return [
        event.model_dump(mode='json', by_alias=True, exclude_none=True)
        for event in events
    ]
